def crear_y_asignar_unidades(apps, schema_editor):
    Maquinaria = apps.get_model('api', 'Maquinaria')
    Unidad = apps.get_model('api', 'UnidadFlota')
    Item = apps.get_model('api', 'ItemContrato')

    for maquinaria in Maquinaria.objects.all():
        for numero in range(1, maquinaria.cantidad + 1):
            Unidad.objects.create(
                maquinaria=maquinaria,
                codigo=f'MQ-{maquinaria.pk:03d}-{numero:02d}',
                permiso_circulacion='excav' in maquinaria.categoria.lower() and numero % 2 == 1,
            )

        procesados = []
        items = Item.objects.filter(
            maquinaria=maquinaria, contrato__estado__in=('PAGADO', 'ENTREGADO')
        ).order_by('fecha_inicio')
        for item in items:
            ocupadas = set()
            for anterior in procesados:
                if anterior.fecha_inicio < item.fecha_fin + timedelta(days=2) and anterior.fecha_fin + timedelta(days=2) > item.fecha_inicio:
                    ocupadas.update(anterior.unidades_asignadas.values_list('id', flat=True))
            libres = Unidad.objects.filter(maquinaria=maquinaria).exclude(id__in=ocupadas)[:item.cantidad]
            item.unidades_asignadas.set(libres)
            procesados.append(item)


